/// An export target: which generated artifact an [`Exporter`] produces.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[non_exhaustive]
pub enum Target {
    /// `tokens.css`: the `:root` custom-property block.
    Css,
    /// The flat `{name: value}` JSON export (`[tokens] json_file`).
    Json,
    /// The Tailwind `theme.extend` mapping (`[tailwind] tokens_file`).
    Tailwind,
    /// Unity USS custom properties, one block per mode (no configured file path yet).
    Uss,
    /// An engine-free C# token class using plain floats (no configured file path yet).
    Csharp,
    /// The DTCG 2025.10 resolver document (no configured file path yet).
    Dtcg,
}

impl Target {
    /// Every target, in the order the managed files are written and reported.
    pub const ALL: [Target; 6] = [
        Target::Css,
        Target::Tailwind,
        Target::Json,
        Target::Uss,
        Target::Csharp,
        Target::Dtcg,
    ];

    /// The `--target` / `--format` spelling (`css`, `json`, `tailwind`).
    pub fn name(self) -> &'static str {
        match self {
            Self::Css => "css",
            Self::Json => "json",
            Self::Tailwind => "tailwind",
            Self::Uss => "uss",
            Self::Csharp => "csharp",
            Self::Dtcg => "dtcg",
        }
    }

    /// Parse the spelling [`Target::name`] prints.
    pub fn parse(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|t| t.name() == name)
    }

    /// The exporter that renders this target.
    pub fn exporter(self) -> &'static dyn Exporter {
        match self {
            Self::Css => &CssExporter,
            Self::Json => &FlatJsonExporter,
            Self::Tailwind => &TailwindExporter,
            Self::Uss => &UssExporter,
            Self::Csharp => &CsharpExporter,
            Self::Dtcg => &DtcgExporter,
        }
    }
}

impl serde::Serialize for Target {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(self.name())
    }
}

impl fmt::Display for Target {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name())
    }
}

/// How drift between the expected text and the file on disk is decided.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Comparison {
    /// Byte for byte.
    Bytes,
    /// After parsing both sides as JSON, so a formatter's re-indent never drifts.
    Json,
}

/// One generated-file format.
pub trait Exporter: Sync {
    /// The target this exporter renders.
    fn target(&self) -> Target;

    /// The deterministic text of the generated file for `tokens` (derived from `spec`).
    fn render(&self, spec: &DesignSpec, tokens: &TokenSet) -> String;

    /// The absolute path `spec` configures for this target's file, or `None` when unset.
    fn path(&self, spec: &DesignSpec) -> Option<PathBuf>;

    /// How a file on disk is compared with [`Exporter::render`].
    fn comparison(&self) -> Comparison;
}

/// Render one target for `spec`.
///
/// # Errors
///
/// [`TokenError`] when the spec produces a colliding token name.
pub fn render_target(spec: &DesignSpec, target: Target) -> Result<String, TokenError> {
    let tokens = TokenSet::from_spec(spec)?;
    Ok(target.exporter().render(spec, &tokens))
}
